const [w, h, r] = readline().split(' ').map(Number);
const [px, py] = readline().split(' ').map(Number);
const [dx, dy, dz] = readline().split(' ').map(Number);

const perim = 2 * (w + h);
const vol = (4/3) * Math.PI * r**3;
const dist = Math.sqrt((dx-px)**2 + (dy-py)**2 + dz**2);

console.log(Math.ceil(perim));
console.log(Math.ceil(vol));
console.log(dist > r ? "true" : "false");
